import{_ as a,a as i}from"./chunks/btn_setting.D7emYdBd.js";import{_ as t}from"./chunks/btn_edit.Bv-WsnWb.js";import{_ as o}from"./chunks/en_nastaveni_notifikace.DJ-aaAt_.js";import{_ as r,o as n,c as s,aa as l}from"./chunks/framework.BAs_AphD.js";const c="/buildary-help-preview/media/en/tickets/en_modul_mu.png",d="/buildary-help-preview/media/en/tickets/en_clenove_projektu2.png",h="/buildary-help-preview/media/en/tickets/en_edit_clena.png",m="/buildary-help-preview/media/en/tickets/en_role_mu2.png",T=JSON.parse('{"title":"Project Settings","description":"","frontmatter":{"title":"Project Settings","wiki":"en:tickets:new_project"},"headers":[],"relativePath":"en/tickets/new_project.md","filePath":"en/tickets/new_project.md","lastUpdated":1794388980000}'),p={name:"en/tickets/new_project.md"};function g(u,e,f,b,y,w){return n(),s("div",null,[...e[0]||(e[0]=[l('<h1 id="project-settings" tabindex="-1">Project Settings <a class="header-anchor" href="#project-settings" aria-label="Permalink to &quot;Project Settings&quot;">​</a></h1><p>For the module to be used, a project must first be created in Buildary and the <strong>Ticket Management module must be activated (enabled)</strong> for it. Modules can be combined in different ways on a project, and individual modules can be activated or deactivated at any time during the project as needed. However, at least one module must always be active on a project. Buildary currently offers three modules:</p><ul><li>Project Diary</li><li>Ticket Management</li><li>Performed Works</li></ul><p>The number of activated modules affects the price (see the <a href="https://www.buildary.online/en/price" target="_blank" rel="noreferrer">online price list</a>).</p><p>The procedure for creating a new project in Buildary is described in <a href="/buildary-help-preview/en/diary/projectsetup">Creating a Project</a>.</p><figure class="shot" style="--w:220px;"><img src="'+a+'" alt="Project Settings" width="200" loading="lazy"></figure><p>You can access <strong>PROJECT SETTINGS</strong> either <strong>from the Project List</strong> by clicking the <img src="'+t+'" alt="pencil" data-no-zoom loading="lazy"> icon next to the relevant project, or, if the project is already open, <strong>from the left navigation panel</strong> by clicking:</p><ul><li>the <strong>project image</strong>, or</li><li>the <strong>blue project name</strong> below it, or</li><li>the <strong>icon</strong> <img src="'+i+'" alt="Project Settings" width="25" data-no-zoom loading="lazy"> below the project name.</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong>Administrator permissions are required to edit a project.</strong></p></div><h3 id="activating-the-module-on-a-project" tabindex="-1">Activating the Module on a Project <a class="header-anchor" href="#activating-the-module-on-a-project" aria-label="Permalink to &quot;Activating the Module on a Project&quot;">​</a></h3><figure class="shot" style="--w:400px;"><img src="'+c+'" alt="Module Activation" loading="lazy"></figure><p>In the project settings (Project Information), the <strong>list of modules</strong> can be found further down the page, below the map.</p><p>By checking the Ticket Management module checkbox and saving the settings using the <strong>Save</strong> button at the bottom of the page, the module is activated.</p><p>The left navigation panel always displays only the modules activated for the given project.</p><p>Therefore, if you do not see a module you need to work with, you need to activate it.</p><p>The module can be deactivated in the opposite way, by unchecking the box and saving the settings.</p><p>There are other areas in the project settings that are related in some way to Ticket Management and should be configured:</p><h2 id="project-team" tabindex="-1">Project Team <a class="header-anchor" href="#project-team" aria-label="Permalink to &quot;Project Team&quot;">​</a></h2><h3 id="project-team-members" tabindex="-1">Project Team Members <a class="header-anchor" href="#project-team-members" aria-label="Permalink to &quot;Project Team Members&quot;">​</a></h3><figure class="shot" style="--w:600px;"><img src="'+d+'" alt="Project Team Members" width="580" loading="lazy"></figure><p><strong>The Project Administrator adds all participants who will be involved in creating, resolving, or approving tickets to the Project Team.</strong></p><p>The role assigned to a Project Team Member determines what permissions the user will have across all modules in use.</p><p>In the existing Project Team Member list, you can open a member&#39;s editing form using the edit icon <img src="'+t+'" alt="pencil" data-no-zoom loading="lazy"> at the end of the row and modify their details.</p><figure class="shot" style="--w:400px;"><img src="'+h+'" alt="Edit Project Team Member" width="380" loading="lazy"></figure><p>The <strong>Project Team Member</strong> is added by the Project Administrator by entering their email address. If the user&#39;s data has already been entered into the system, the other user details (first name, last name, and phone number) are filled in automatically according to their profile. Otherwise, the administrator enters them manually. The member is then assigned to the relevant company, if their organization is already in the list. If it is not, the administrator adds the organization in the adjacent <strong>Companies</strong> tab and then assigns it to the user.</p><p>The form also contains 2 additional fields related to the Ticket Management module:</p><p><strong>Default Role in Authorized Persons</strong> → by selecting a role, the administrator determines the permissions the user will have. These are preset according to standard practices, but the administrator can individually adjust the permissions for each role according to their specific needs (see below).</p><figure class="shot" style="--w:300px;"><img src="'+o+'" alt="Ticket Management Notification Settings" width="280" loading="lazy"></figure><p><strong>Email Notification - Ticket Management</strong> → allows you to select the appropriate notification method for a user regarding a ticket for which they are an assignee or approver:</p><ul><li><strong>None</strong> ⇒ the user will not receive any notifications</li><li><strong>HTML Email</strong> ⇒ when a ticket is created, the user will receive an email notification about the ticket</li><li><strong>Email with Event</strong> ⇒ when a ticket is created, an email notification will be sent and an event will also be added to the calendar, on the planned due date. Updates will also be sent when the ticket is changed or deleted</li><li><strong>Summary Email</strong> ⇒ a summary message containing all new or updated tickets for the entire day will be sent. These emails are automatically sent every night.</li></ul><h3 id="member-roles" tabindex="-1">Member Roles <a class="header-anchor" href="#member-roles" aria-label="Permalink to &quot;Member Roles&quot;">​</a></h3><figure class="shot" style="--w:400px;"><img src="'+m+'" alt="Member Roles" width="380" loading="lazy"></figure><p>The Member Roles tab contains a list of roles with preset permissions for all modules. <strong><strong>User permissions for the Ticket Management module</strong></strong> form a very simple system. Only two parameters are monitored, namely who can:</p><ul><li><strong>VIEW ALL TICKETS</strong> ⇒ a user with this permission can see all tickets, including those with which they have no relationship. If this permission is not enabled, the user can only see tickets for which they are the author, assignee, or approver</li><li><strong>CREATE NEW TICKETS</strong> ⇒ a user with this permission can create a new ticket. If this permission is not enabled, the user cannot create a new ticket, but can edit tickets they are assigned to resolve or approve.</li></ul>',34)])])}const P=r(p,[["render",g]]);export{T as __pageData,P as default};
